class PullRequest:
    def __init__(self, number, branch, target="main"):
        self.number = number
        self.branch = branch
        self.target = target
        self.comments = []
        self.approved = False

    def comment(self, author, text):
        self.comments.append((author, text))

    def approve(self, author):
        self.approved = True
        self.comments.append((author, "approved"))

    def merge(self):
        if not self.approved:
            raise ValueError("no se puede fusionar sin aprobación")
        return f"#{self.number} fusionado: {self.branch} -> {self.target}"


pr = PullRequest(42, "feature/login")
pr.comment("ana", "falta validar el email")
pr.comment("ana", "corregido, aprobando")
pr.approve("ana")
for author, text in pr.comments:
    print(f"{author}: {text}")
print(pr.merge())
